'use strict';

// Only observes responses generated by the selected ticket tab. No replay,
// request modification, cookies, login/member response bodies, or raw exports.
(function install(root) {
  function allowedTabUrl(value) {
    try {
      const u = new URL(value);
      if (u.username || u.password || u.protocol !== 'https:') return false;
      return u.origin === 'https://nol.yanolja.com' && (u.pathname === '/ticket' || u.pathname.startsWith('/ticket/')) ||
        u.origin === 'https://tickets.interpark.com' && /^\/(?:gates|waiting|onestop)(?:\/|$)/.test(u.pathname);
    } catch { return false; }
  }

  function createBaseballNetworkObserver({chrome, emit = () => {}, parsers, allowTabUrl = allowedTabUrl, now = () => performance.now()}) {
    if (!chrome?.debugger || !chrome?.tabs || !parsers?.metadata || !parsers?.seatNetwork || !parsers?.entryNetwork) throw Error('네트워크 관찰 구성 요소가 없습니다.');
    const states = new Map(), attaching = new Map(), popupParents = new Map();
    const publish = event => { try { const documentId=states.get(event.tabId)?.documentId;emit(documentId?{...event,documentId}:event); } catch {} };
    const snapshot = tabId => {
      const s = states.get(tabId);
      return {sequence: s?.sequence || 0, healthy: s?.healthy === true,
        pending: s ? [...s.pending.values()].filter(r => r.category === 'seat').map(r => ({seq:r.seq,kind:r.kind,seatIds:[...r.seatIds]})) : [],
        results: s ? s.results.map(r => ({...r,seatIds:[...r.seatIds]})) : []};
    };
    const sendSnapshot = tabId => publish({type:'network',tabId,snapshot:snapshot(tabId)});
    const current = (s, generation = s.generation) => states.get(s.tabId) === s && s.generation === generation;
    function reset(tabId, reason = 'navigation') {
      const s = states.get(tabId); if (!s) return;
      s.generation++; s.pending.clear(); s.results.length = 0; s.contextKey = null;
      publish({type:'metadata-reset',tabId,reason}); sendSnapshot(tabId);
    }
    function finishSeat(s, requestId, result) {
      const r = s.pending.get(requestId); if (!r || r.category !== 'seat') return;
      s.pending.delete(requestId);
      s.results.push({seq:r.seq,kind:r.kind,status:result.status,seatIds:result.seatIds});
      if (s.results.length > 256) s.results.splice(0,s.results.length-256);
      sendSnapshot(s.tabId);
    }
    function finishEntry(s, requestId, kind, p, overrideStatus) {
      const r = s.pending.get(requestId); if (!r || r.category !== 'entry') return;
      s.pending.delete(requestId);
      const event = {kind,atMono:now(),seq:r.seq};
      const status = overrideStatus ?? r.statusCode;
      if (Number.isInteger(status) && status >= 100 && status <= 599) event.status=status;
      if (Number.isFinite(p.timestamp) && Number.isFinite(r.startedAt) && p.timestamp >= r.startedAt) event.durationMs=(p.timestamp-r.startedAt)*1000;
      publish({type:'entry',tabId:s.tabId,event});
    }
    function lost(s, reason = 'unknown', detachReason) {
      if (!current(s) || s.lossReported) return;
      // Keep the first loss cause: one detach may also trigger tab removal or
      // an in-flight protocol error. Never export raw exception text or URLs.
      s.lossReported=true;
      s.healthy=false;
      for (const [id,r] of [...s.pending]) {
        if (r.category==='seat') finishSeat(s,id,{status:'uncertain',seatIds:[]});
      }
      s.generation++; s.pending.clear();
      sendSnapshot(s.tabId);
      const safeReason=['debugger-detached','target-closed','observer-error','pending-overflow','manual-detach','unknown'].includes(reason)?reason:'unknown';
      const event={kind:'observer-lost',atMono:now(),reason:safeReason};
      if (detachReason==='target_closed' || detachReason==='canceled_by_user') event.detachReason=detachReason;
      publish({type:'entry',tabId:s.tabId,event});
    }
    function decodeBody(response, limit) {
      if (typeof response?.body !== 'string' || response.body.length > Math.ceil(limit*4/3)+4) throw Error('response limit');
      const body = response.base64Encoded ? new TextDecoder().decode(Uint8Array.from(atob(response.body), c=>c.charCodeAt(0))) : response.body;
      if (body.length > limit) throw Error('response limit');
      return body;
    }
    function gradesRequest(request) {
      let u,body;try { u=new URL(request.url); } catch { return null; }
      if (u.origin!=='https://tickets.interpark.com' || u.pathname!=='/onestop/gql' || request.method!=='POST' || u.username || u.password) return null;
      try { body=JSON.parse(request.postData); } catch { return null; }
      if (!body || !/\bquery\s+GetRemainSeats\b/.test(body.query||'') || (body.operationName && body.operationName!=='GetRemainSeats')) return null;
      return {contextKey:JSON.stringify(body.variables || {})};
    }
    async function onEvent(source,method,p) {
      if (source?.sessionId || !Number.isInteger(source?.tabId) || !p || typeof p.requestId!=='string') return;
      const s=states.get(source.tabId); if (!s?.healthy) return;
      const id=p.requestId;
      if (method==='Network.requestWillBeSent') {
        const old=s.pending.get(id);
        if (old) {
          if (!p.redirectResponse) return;
          if (old.category==='entry') finishEntry(s,id,'finished',p,p.redirectResponse.status);
          else if (old.category==='seat') finishSeat(s,id,{status:'uncertain',seatIds:[]});
          else s.pending.delete(id);
        }
        const request=p.request;
        if (!request || typeof request.url!=='string') return;
        let u;try {u=new URL(request.url);} catch {return;}
        if (u.username || u.password) return;
        let record;
        if (parsers.entryNetwork.isEntryRequest(request)) {
          record={category:'entry',seq:++s.entrySequence,startedAt:p.timestamp};
        } else if (parsers.metadata.metadataUrl(request.url) && request.method==='GET') {
          record={category:'metadata'};
        } else {
          const grade=gradesRequest(request);
          if (grade) {
            if (s.contextKey!==null && s.contextKey!==grade.contextKey) reset(s.tabId,'context');
            s.contextKey=grade.contextKey;record={category:'grades'};
          } else {
            const seat=parsers.seatNetwork.classifyRequest(request);
            if (seat) record={category:'seat',...seat,seq:++s.sequence};
          }
        }
        if (!record) return;
        if (s.pending.size>=1024) {lost(s,'pending-overflow');return;}
        s.pending.set(id,{...record,generation:s.generation,statusCode:0});
        if (record.category==='entry') publish({type:'entry',tabId:s.tabId,event:{kind:'request',atMono:now(),seq:record.seq}});
        if (record.category==='seat') sendSnapshot(s.tabId);
        return;
      }
      const record=s.pending.get(id);if (!record) return;
      if (method==='Network.responseReceived') {record.statusCode=p.response?.status || 0;return;}
      if (method==='Network.loadingFailed') {
        if (record.category==='seat') finishSeat(s,id,{status:'uncertain',seatIds:[]});
        else if (record.category==='entry') finishEntry(s,id,'failed',p);
        else s.pending.delete(id);
        return;
      }
      if (method!=='Network.loadingFinished') return;
      if (record.category==='entry') {finishEntry(s,id,'finished',p);return;}
      const generation=s.generation;
      try {
        if (record.category!=='seat' && record.statusCode!==200) {s.pending.delete(id);return;}
        const limit=record.category==='metadata'?12000000:1000000;
        if (p.encodedDataLength>limit) throw Error('response limit');
        const response=await chrome.debugger.sendCommand({tabId:s.tabId},'Network.getResponseBody',{requestId:id});
        if (!current(s,generation) || s.pending.get(id)!==record) return;
        const body=decodeBody(response,limit);
        if (record.category==='seat') finishSeat(s,id,parsers.seatNetwork.classifyResponse(record,record.statusCode,body));
        else {
          s.pending.delete(id);
          if (record.category==='metadata') {
            const rows=parsers.metadata.parseMetadata(body).filter(row=>
              ['id','block','blockKey','gradeCode','segment'].every(key=>typeof row[key]==='string' && row[key].length<=300) &&
              (row.grade==null || typeof row.grade==='string' && row.grade.length<=300) &&
              Array.isArray(row.neighbors) && row.neighbors.length<=2 && row.neighbors.every(id=>typeof id==='string' && id.length<=300));
            if (rows.length>50000) throw Error('seat limit');
            for(let offset=0;offset<rows.length;offset+=1000)publish({type:'metadata',tabId:s.tabId,rows:rows.slice(offset,offset+1000)});
          } else {
            const values=JSON.parse(body)?.data?.getRemainSeats;
            if (Array.isArray(values)) publish({type:'grades',tabId:s.tabId,rows:values.filter(r=>r && r.seatGrade!=null && String(r.seatGrade).length<=300 && typeof r.seatGradeName==='string' && r.seatGradeName.length<=300).slice(0,500).map(r=>({code:String(r.seatGrade),name:r.seatGradeName}))});
          }
        }
      } catch {
        if (!current(s,generation)) return;
        if (record.category==='seat') finishSeat(s,id,{status:'uncertain',seatIds:[]});
        else {s.pending.delete(id);publish({type:'metadata-error',tabId:s.tabId,message:'좌석 상세 정보를 읽지 못했습니다. 자동 선택을 대기합니다.'});}
      }
    }
    chrome.debugger.onEvent.addListener((source,method,p)=>{void onEvent(source,method,p).catch(()=>{const s=states.get(source?.tabId);if(s)lost(s,'observer-error');});});
    chrome.debugger.onDetach.addListener((source,reason)=>{
      const s=states.get(source?.tabId);
      if(s)lost(s,reason==='target_closed'?'target-closed':'debugger-detached',reason);
    });
    const detach=async (tabId,cancelAttach=true,reason='manual-detach')=> {
      if(cancelAttach && attaching.has(tabId))attaching.get(tabId).cancelled=true;
      popupParents.delete(tabId);
      const s=states.get(tabId);if(!s)return;
      lost(s,reason);states.delete(tabId);
      try {await chrome.debugger.detach({tabId});} catch {}
    };
    async function attach(tabId) {
      if (!Number.isInteger(tabId) || tabId<0) throw Error('연결할 Chrome 탭을 선택해 주세요.');
      if (attaching.has(tabId)) return attaching.get(tabId).task;
      const operation={cancelled:false,task:null};
      const tabAllowed=tab=>allowTabUrl(tab?.url) || ((tab?.url==='about:blank' || (!tab?.url && allowTabUrl(tab?.pendingUrl))) && popupParents.get(tabId)===tab.openerTabId && states.get(tab.openerTabId)?.healthy===true);
      const task=(async()=>{
        const tab=await chrome.tabs.get(tabId);
        if(operation.cancelled)throw Error('연결이 취소되었습니다.');
        if (!tabAllowed(tab)) throw Error('지원하는 NOL 야구 예매 페이지에서 연결해 주세요.');
        if (states.get(tabId)?.healthy) return snapshot(tabId);
        if (states.has(tabId)) await detach(tabId,false);
        if(operation.cancelled)throw Error('연결이 취소되었습니다.');
        const s={tabId,generation:0,sequence:0,entrySequence:0,healthy:false,pending:new Map(),results:[],contextKey:null};
        states.set(tabId,s);sendSnapshot(tabId);
        try {
          await chrome.debugger.attach({tabId},'1.3');
          if (!current(s) || operation.cancelled) {try{await chrome.debugger.detach({tabId});}catch{}throw Error('연결이 취소되었습니다.');}
          // Attach may finish after the user navigates away; check again before enabling observation.
          if (!tabAllowed(await chrome.tabs.get(tabId))) throw Error('예매 페이지가 변경되어 연결을 중지했습니다.');
          if (!current(s) || operation.cancelled) throw Error('연결이 취소되었습니다.');
          const frameGeneration=s.generation;
          const frame=await chrome.webNavigation?.getFrame?.({tabId,frameId:0}).catch(()=>null);
          if (!current(s) || operation.cancelled) throw Error('연결이 취소되었습니다.');
          if(s.generation===frameGeneration && typeof frame?.documentId==='string')s.documentId=frame.documentId;
          await chrome.debugger.sendCommand({tabId},'Network.enable',{maxTotalBufferSize:16000000,maxResourceBufferSize:12000000});
          if (!current(s) || operation.cancelled) throw Error('연결이 취소되었습니다.');
          s.healthy=true;reset(tabId,'attach');return snapshot(tabId);
        } catch {
          if (current(s)) {lost(s,'observer-error');states.delete(tabId);}
          try{await chrome.debugger.detach({tabId});}catch{}
          throw Error('Chrome의 좌석 응답 관찰에 연결하지 못했습니다. 확장 권한과 탭 상태를 확인해 주세요.');
        }
      })();
      operation.task=task;attaching.set(tabId,operation);try{return await task;}finally{attaching.delete(tabId);}
    }
    chrome.webNavigation?.onCommitted?.addListener(details=>{
      if(details.frameId!==0 || !states.has(details.tabId))return;
      states.get(details.tabId).documentId=details.documentId;
      if(details.url==='about:blank' && popupParents.has(details.tabId))return;
      popupParents.delete(details.tabId);
      if(!allowTabUrl(details.url))void detach(details.tabId);
      else reset(details.tabId,'navigation');
    });
    chrome.tabs.onCreated?.addListener(tab=>{
      if(!Number.isInteger(tab.id) || !Number.isInteger(tab.openerTabId) || !states.get(tab.openerTabId)?.healthy)return;
      // Only descendants of a watched ticket tab receive early observation.
      // A blank popup is temporary; its first real navigation is revalidated.
      if(tab.url!=='about:blank' && !allowTabUrl(tab.url) && !allowTabUrl(tab.pendingUrl))return;
      popupParents.set(tab.id,tab.openerTabId);
      void attach(tab.id).catch(()=>popupParents.delete(tab.id));
    });
    chrome.tabs.onRemoved?.addListener(tabId=>{void detach(tabId,true,'target-closed');});
    return {attach,detach,snapshot,reset,detachAll:()=>{for(const operation of attaching.values())operation.cancelled=true;popupParents.clear();return Promise.allSettled([...states.keys()].map(id=>detach(id)));}};
  }
  root.createBaseballNetworkObserver=createBaseballNetworkObserver;
  if(typeof module!=='undefined' && module.exports)module.exports={createBaseballNetworkObserver,allowedTabUrl};
})(globalThis);
